using ValveResourceFormat;using ValveResourceFormat.ResourceTypes;using ValveResourceFormat.Serialization.KeyValues;using ValveKeyValue;using System.Text.Json;
var root=args[0];var reports=new List<object>();
foreach(var name in new[]{"wood","metal"}){
 var src="work/laugh-color-fix/stage/materials/models/naidan_props/park_"+name+".vmat_c";using var r=new Resource();r.Read(src);var kv=(KeyValuesOrNTRO)r.DataBlock!;var before=kv.Data["m_textureParams"].Values.Where(x=>x["m_name"].ToString()!="g_tColor").Select(x=>x.ToKV3String()).ToArray();var dyn=kv.Data["m_dynamicParams"].ToKV3String();
 using var carrier=new Resource();carrier.Read(root+"/carriers/park_"+name+"_bake.vmat_c");var ck=((KeyValuesOrNTRO)carrier.DataBlock!).Data;var color=ck["m_textureParams"].Values.Single(x=>x["m_name"].ToString()=="g_tColor")["m_pValue"];var newName=color.ToString();
 var entry=kv.Data["m_textureParams"].Values.Single(x=>x["m_name"].ToString()=="g_tColor");entry["m_pValue"]=color;
 var tint=KVObject.Array();foreach(var x in new[]{1f,1f,1f,0f})tint.Add(x);kv.Data["m_vectorParams"].Values.Single(x=>x["m_name"].ToString()=="g_vColorTint1")["m_value"]=tint;
 var reference=carrier.ExternalReferences!.ResourceRefInfoList.Single(x=>x.Name==newName);r.ExternalReferences!.ResourceRefInfoList.Add(reference);
 using var data=new MemoryStream();kv.Serialize(data);using var refs=new MemoryStream();r.ExternalReferences.Serialize(refs);var dest=root+"/stage/materials/models/naidan_props/park_"+name+".vmat_c";ReplaceData(src,dest,new(){["DATA"]=data.ToArray(),["RERL"]=refs.ToArray()});
 using var check=new Resource();check.Read(dest);var k=((KeyValuesOrNTRO)check.DataBlock!).Data;if(!before.SequenceEqual(k["m_textureParams"].Values.Where(x=>x["m_name"].ToString()!="g_tColor").Select(x=>x.ToKV3String()))||dyn!=k["m_dynamicParams"].ToKV3String())throw new Exception("Native noncolor material changed");var readColor=k["m_textureParams"].Values.Single(x=>x["m_name"].ToString()=="g_tColor")["m_pValue"].ToString();if(readColor!=newName||!File.Exists(root+"/stage/"+readColor+"_c"))throw new Exception("Baked dependency missing");reports.Add(new{name,color=readColor,otherMapsExact=true,dynamicsExact=true,whiteTint=true});
}
using(var hero=new Resource()){hero.Read("work/laugh-color-fix/stage/models/heroes_wip/baba/baba.vmdl_c");var model=(Model)hero.DataBlock!;var assignments=new List<object>();foreach(var mesh in model.GetEmbeddedMeshes().Where(x=>x.Name.StartsWith("base_model"))){var calls=mesh.Mesh.Data["m_sceneObjects"].Values.SelectMany(x=>x["m_drawCalls"].Values).ToArray();var names=calls.Select(x=>Mesh.GetMaterialName(x)).ToArray();if(!names.Any(x=>x!=null&&x.Contains("park_wood"))||!names.Any(x=>x!=null&&x.Contains("park_metal")))throw new Exception("Chair actual drawcall missing in "+mesh.Name);assignments.Add(new{mesh=mesh.Name,materials=names});}if(assignments.Count!=4)throw new Exception("Expected 4 base LODs");reports.Add(new{compiledMeshAssignments=assignments});}
File.WriteAllText(root+"/material-validation.json",JsonSerializer.Serialize(reports,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("Baked albedos bound to native chair materials. Other native maps and bead dynamics unchanged.");
static void ReplaceData(string input,string output,Dictionary<string,byte[]> blocks){var raw=File.ReadAllBytes(input);int table=8+BitConverter.ToInt32(raw,8);int count=BitConverter.ToInt32(raw,12);using var ms=new MemoryStream();using var w=new BinaryWriter(ms);w.Write(raw,0,16);w.Write(new byte[count*12]);var entries=new List<(byte[] Tag,int At,int Len)>();for(int i=0;i<count;i++){int p=table+12*i;var tag=raw[p..(p+4)];int start=p+4+BitConverter.ToInt32(raw,p+4),length=BitConverter.ToInt32(raw,p+8);while(ms.Position%4!=0)w.Write((byte)0);int at=(int)ms.Position;var payload=blocks.GetValueOrDefault(System.Text.Encoding.ASCII.GetString(tag))??raw[start..(start+length)];w.Write(payload);entries.Add((tag,at,payload.Length));}ms.Position=0;w.Write((uint)ms.Length);ms.Position=8;w.Write(8);w.Write(count);for(int i=0;i<count;i++){int p=16+i*12;ms.Position=p;w.Write(entries[i].Tag);w.Write(entries[i].At-(p+4));w.Write(entries[i].Len);}File.WriteAllBytes(output,ms.ToArray());}
